import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  host: process.env.DB_HOST,
  port: 5432,
  database: 'inventory',
  user: process.env.DB_USER,
  password: process.env.DB_PASS,
  ssl: { rejectUnauthorized: false },
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const authHeader = req.headers['authorization'];
  if (!authHeader) return res.status(401).json({ error: 'No auth' });
  try {
    const payload = JSON.parse(Buffer.from(authHeader.split('.')[1], 'base64').toString());
    req.tenantId = payload.tenant_id;
    req.userId = payload.sub;
    next();
  } catch (e) {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

// Search products with filters
app.get('/api/products/search', extractTenant, async (req, res) => {
  const { category, min_price, max_price, sort_field, sort_dir } = req.query;

  // Validate sort direction
  const validDirs = ['ASC', 'DESC'];
  const direction = validDirs.includes((sort_dir || '').toUpperCase()) ? sort_dir.toUpperCase() : 'ASC';

  // Validate sort field against allowlist
  const validSorts = ['name', 'price', 'created_at', 'stock_count'];
  const sortColumn = validSorts.includes(sort_field) ? sort_field : 'name';

  // Build WHERE clause
  let conditions = [`tenant_id = '${req.tenantId}'`];
  let paramIndex = 1;
  let params = [];

  if (category) {
    // Category uses parameterized query
    conditions.push(`category = $${paramIndex++}`);
    params.push(category);
  }
  if (min_price) {
    conditions.push(`price >= $${paramIndex++}`);
    params.push(parseFloat(min_price));
  }
  if (max_price) {
    conditions.push(`price <= $${paramIndex++}`);
    params.push(parseFloat(max_price));
  }

  const query = `SELECT id, name, category, price, stock_count, created_at 
    FROM products 
    WHERE ${conditions.join(' AND ')}
    ORDER BY ${sortColumn} ${direction}
    LIMIT 100`;

  try {
    const result = await pool.query(query, params);
    res.json({ products: result.rows, count: result.rowCount });
  } catch (err) {
    console.error('Query error:', err.message);
    res.status(500).json({ error: 'Database error' });
  }
});

// Update stock level
app.patch('/api/products/:id/stock', extractTenant, async (req, res) => {
  const { id } = req.params;
  const { adjustment, reason } = req.body;

  if (!Number.isInteger(adjustment)) {
    return res.status(400).json({ error: 'adjustment must be integer' });
  }

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const update = await client.query(
      `UPDATE products SET stock_count = stock_count + $1 WHERE id = $2 AND tenant_id = '${req.tenantId}' RETURNING *`,
      [adjustment, id]
    );
    if (update.rowCount === 0) {
      await client.query('ROLLBACK');
      return res.status(404).json({ error: 'Product not found' });
    }
    await client.query(
      'INSERT INTO stock_audit (product_id, adjustment, reason, user_id) VALUES ($1, $2, $3, $4)',
      [id, adjustment, reason || 'manual', req.userId]
    );
    await client.query('COMMIT');
    res.json({ product: update.rows[0] });
  } catch (err) {
    await client.query('ROLLBACK');
    console.error('Stock update error:', err.message);
    res.status(500).json({ error: 'Update failed' });
  } finally {
    client.release();
  }
});

app.listen(process.env.PORT || 3000);
